private GUPPriceComponentCodePriceAttributeGroupCombination getPriceAttributeGroupCombination()
{
    GUPPriceComponentCode componentCode;
    select firstonly componentCode where componentCode.RelationType == GUPPriceComponent::SalesTradeAgreement;
    GUPPriceComponentCodePriceAttributeGroupCombination combination = GUPPriceComponentCodePriceAttributeGroupCombination::findByNameAndComponentCode(this.PriceComponentCombination, componentCode, true);
    if (!combination)
    {
        throw error(strfmt("@GlobalUnifiedPricing:GUPPriceComponentCodePriceAttributeGroupCombination_NotExisting", this.PriceComponentCombination));
    }
    return  combination;
}

private void updateAttributeGroupCombination(PriceDiscAdmTable _journal)
{
    PriceDiscAdmName journalName = PriceDiscAdmName::find(_journal.JournalName);
    if (!journalName.PriceDiscPriceAttributeEnable)
    {
        throw error(strfmt("@GlobalUnifiedPricing:PriceDiscAdmName_AttributeNotEnabled", journalName.JournalName));
    }
    GUPPriceComponentCodePriceAttributeGroupCombination combination = this.getPriceAttributeGroupCombination();
    _journal.PriceComponentCombination = combination.RecId;
}

public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    if (_dataSourceCtx.name() == dataEntityDataSourceStr(TradeOpenTradeAgreementJournalHeaderV2Entity, PriceDiscAdmTable))
    {
        if (this.PriceComponentCombination)
        {
            PriceDiscAdmTable journal = _dataSourceCtx.getBuffer();
            this.updateAttributeGroupCombination(journal);
        }
    }
    return next insertEntityDataSource(_entityCtx, _dataSourceCtx);
}

public boolean updateEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    if (_dataSourceCtx.name() == dataEntityDataSourceStr(TradeOpenTradeAgreementJournalHeaderV2Entity, PriceDiscAdmTable))
    {
        if (this.PriceComponentCombination)
        {
            PriceDiscAdmTable journal = _dataSourceCtx.getBuffer();
            this.updateAttributeGroupCombination(journal);
        }
    }
    return next updateEntityDataSource(_entityCtx, _dataSourceCtx);
}

public void initializeEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    next initializeEntityDataSource(_entityCtx, _dataSourceCtx);
    if (_dataSourceCtx.name() ==  dataEntityDataSourceStr(TradeOpenTradeAgreementJournalHeaderV2Entity, GUPPriceComponentCodePriceAttributeGroupCombination))
    {
        _dataSourceCtx.setDataSaved(true);
        _dataSourceCtx.setDatabaseOperation(DataEntityDatabaseOperation::Update);
    }
}
